$('chat-form').onsubmit=async e=>{e.preventDefault();const text=$('chat-input').value.trim();if(!text||!online||!selected)return;const message={id:crypto.randomUUID(),room:selected,name,text:text.slice(0,500),sender:id};const result=await lobby.send({type:'broadcast',event:'chat',payload:message});if(result==='ok'){roomChat(selected).push(message);chatByRoom[selected]=roomChat(selected).slice(-100);$('chat-input').value='';renderChat();}else feedback('No se pudo enviar el mensaje. Intentá de nuevo.');};
