function createPlayer(r){playerLoadAt=Date.now();loaded=r.video_id;playbackKey=r.video_id+':'+r.singer_client+':'+r.updated_at;$('player-empty').hidden=true;const frame=el('iframe','');frame.id='player';frame.title='Reproductor de karaoke';frame.allow='autoplay; encrypted-media; picture-in-picture';frame.referrerPolicy='strict-origin-when-cross-origin';frame.src='https://www.youtube-nocookie.com/embed/'+r.video_id+'?'+new URLSearchParams({enablejsapi:'1',playsinline:'1',origin:location.origin,start:String(Math.floor(resumeTarget(r))),autoplay:'0',controls:'0',disablekb:'1',fs:'0'});$('player').replaceWith(frame);player=new YT.Player('player',{events:{onReady:()=>{player.setVolume(host()?65:35);playerReady=true;turnClock();syncPlayer();},onStateChange:e=>{if(e.data===1)confirmStart();if(e.data===0&&host()&&states[selected]?.phase==='playing'&&states[selected]?.started_at)client.rpc('finish_song',{room:selected,client:id}).then(refresh);},onError:()=>feedback('YouTube no permite reproducir este video. Podés parar la canción.'),onAutoplayBlocked:()=>{$('enable-audio').hidden=false;}}});}
