$('cam').onclick=async()=>{if(!voice)return;$('cam').disabled=true;let active;try{active=await voice.toggle('video');}catch(error){const message=error?.name==='NotAllowedError'||error?.name==='SecurityError'?'Permití la cámara para este sitio desde la configuración del navegador.':error?.name==='NotFoundError'?'Este dispositivo no informó ninguna cámara disponible.':'El navegador no pudo iniciar la cámara ('+(error?.name||'error desconocido')+').';feedback(message,8000);$('cam').disabled=false;return;}$('cam').textContent='📷';$('cam').setAttribute('aria-label',active?'Cámara encendida':'Cámara apagada');$('cam').setAttribute('aria-pressed',String(active));render();try{await track();}catch{feedback(active?'La cámara está encendida. Reconectando su estado con la sala…':'Cámara apagada.',4000);}finally{$('cam').disabled=false;}};
