$('create-room').onclick=()=>{$('room-name').value='';$('room-dialog').showModal();$('room-name').focus();};
$('room-close').onclick=()=>$('room-dialog').close();
$('room-dialog').onclick=e=>{if(e.target===$('room-dialog'))$('room-dialog').close();};
$('room-form').onsubmit=async e=>{e.preventDefault();const roomName=$('room-name').value.trim();if(roomName.length<2)return;const button=$('room-form').querySelector('[type=submit]');button.disabled=true;try{const {data,error}=await client.rpc('create_room',{room_name:roomName});if(error)throw error;await refresh();$('room-dialog').close();await join(data);feedback('Sala creada. Quedará disponible permanentemente.');}catch(error){feedback(error.message||'No se pudo crear la sala.');}finally{button.disabled=false;}};
const cache=new Map();
$('search').onsubmit=async e=>{e.preventDefault();if(busy)return;const q=$('query').value.trim();if(!q)return;
 busy=true;$('search-go').disabled=true;$('search-status').textContent='Buscando karaokes…';
 try{let results=cache.get(q.toLowerCase());if(!results){const {data,error}=await client.functions.invoke('youtube-search',{body:{action:'search',query:q}});if(error)throw new Error(data?.error||'No se pudo buscar en YouTube.');if(data?.error)throw new Error(data.error);results=data?.items||[];cache.set(q.toLowerCase(),results);}
 let resultPage=0;const showResults=()=>{$('results').replaceChildren(...results.slice(resultPage*2,resultPage*2+2).map(item=>{const card=el('article','result');const img=el('img','');img.src=item.snippet.thumbnails.medium.url;img.alt='';const title=new DOMParser().parseFromString(item.snippet.title,'text/html').body.textContent;const button=el('button','','Cantar');button.dataset.videoId=item.id.videoId;button.onclick=async()=>{button.dataset.adding='true';button.disabled=true;panel('chat');try{const {data:detail,error:detailError}=await client.functions.invoke('youtube-search',{body:{action:'detail',videoId:item.id.videoId}});if(detailError)throw new Error(detail?.error||'No se pudo consultar la duración.');if(detail?.error)throw new Error(detail.error);const seconds=detail?.seconds;if(!Number.isInteger(seconds))throw new Error('Este video no tiene una duración disponible.');await pulse();const {error}=await client.rpc('enqueue_song',{room:selected,video:item.id.videoId,song_title:title,singer:name,client:id,seconds});if(error)throw error;await refresh();if(!queue.some(s=>s.client_id===id&&s.video_id===item.id.videoId)&&!(host()&&states[selected]?.video_id===item.id.videoId))throw new Error('La canción no quedó en la lista. Volvé a entrar a la sala.');feedback('Canción agregada a la lista.');}catch(e){feedback(e.message);}finally{delete button.dataset.adding;updateResultButtons();}};card.append(img,el('h3','',title),el('small','',item.snippet.channelTitle),button);return card;}));if(results.length>2){const nav=el('div','pages');const label=el('span','',`${resultPage+1} / ${Math.ceil(results.length/2)}`);for(const [text,delta]of [['←',-1],['→',1]]){const b=el('button','',text);b.setAttribute('aria-label',delta<0?'Resultados anteriores':'Más resultados');b.disabled=resultPage+delta<0||resultPage+delta>=Math.ceil(results.length/2);b.onclick=()=>{resultPage+=delta;showResults();};nav.append(b);}nav.append(label);$('results').append(nav);}};showResults();updateResultButtons();$('search-status').textContent=results.length?`${results.length} karaokes encontrados.`:'No encontramos títulos con “karaoke”. Probá con otro nombre.';
 }catch(error){$('search-status').textContent=error.message;}finally{busy=false;$('search-go').disabled=false;}
};
async function start(){render();if(!config.supabaseUrl||!config.supabaseKey){$('connection').textContent='Salas pendientes de conexión a Supabase. Todavía no se puede entrar.';return;}
 try{const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2');client=createClient(config.supabaseUrl,config.supabaseKey,{auth:{storage:localStorage,persistSession:true,autoRefreshToken:true}});const {data:session}=await client.auth.getSession();let user=session.session?.user;if(!user){const {data,error}=await client.auth.signInAnonymously();if(error)throw error;user=data.user;}uid=user.id;accessToken=(await client.auth.getSession()).data.session?.access_token;client.auth.onAuthStateChange((_event,session)=>{accessToken=session?.access_token;});
 await clock();await refresh();lobby=client.channel('canta-lobby',{config:{presence:{key:id}}});lobby.on('broadcast',{event:'chat'},({payload:m})=>{if(!states[m.room]||typeof m.text!=='string'||typeof m.name!=='string'||!members.some(p=>p.id===m.sender&&p.roomId===m.room))return;roomChat(m.room).push({...m,name:m.name.slice(0,60),text:m.text.slice(0,500)});chatByRoom[m.room]=roomChat(m.room).slice(-100);if(selected===m.room)renderChat();}).on('broadcast',{event:'reaction'},({payload:r})=>{if(r?.room!==selected||!members.some(member=>member.id===r.from&&member.roomId===selected))return;showReaction(r.from,r.type);}).on('presence',{event:'sync'},()=>refresh().catch(()=>{})).on('broadcast',{event:'signal'},({payload:p})=>{if(p.to!==id||p.room!==selected)return;if(!members.some(m=>m.id===p.from&&m.roomId===selected)){if(pendingSignals.length<100)pendingSignals.push({...p,received:Date.now()});return;}voice?.receive(p.from,p.data).catch(()=>feedback('No se pudo conectar la voz. Volvé a entrar en la sala.'));}).on('postgres_changes',{event:'*',schema:'public',table:'song_queue'},()=>refresh().catch(()=>{})).on('postgres_changes',{event:'*',schema:'public',table:'rooms'},({new:r,old})=>{if(r?.id)states[r.id]=r;else if(old?.id)delete states[old.id];render();syncPlayer();}).subscribe(async status=>{online=status==='SUBSCRIBED';$('connection').textContent=online?'● Salas conectadas · Entrá y compartí tu enlace':'Reconectando salas…';render();if(online){await track();await refresh();if(!ready){ready=true;const room=new URLSearchParams(location.search).get('sala')||decodeURIComponent(location.hash.slice(1));if(states[room])await join(room);else document.documentElement.classList.remove('room-route-pending');}}});
 setInterval(async()=>{if(!online||advancing)return;advancing=true;try{await pulse();const {error}=await client.rpc('room_sweep');if(error)throw error;await refresh();if($('feedback').textContent==='Comprobando conexión con la sala…')feedback('');}catch(e){if(selected)feedback('Comprobando conexión con la sala…');}finally{advancing=false;}},2000);
 setInterval(()=>{turnClock();syncPlayer();},250);setInterval(()=>clock().catch(()=>{}),60000);

 }catch(e){$('connection').textContent='No se pudo conectar: '+e.message;}}
window.addEventListener('pagehide',()=>{voice?.close();roomAudio.clear();lobby?.untrack();});start();

if(syntheticTest){
 const controls=el('div',''),run=el('button','','Iniciar prueba sintética en D'),stop=el('button','','Detener prueba');controls.append(run,stop);controls.style.cssText='position:fixed;top:0;right:0;z-index:100;background:#19231e;padding:6px';document.body.append(controls);
 let testContext,testTimer,testOsc;
 const cleanup=()=>{clearInterval(testTimer);testOsc?.stop();testOsc=null;testContext?.close();testContext=null;};
 stop.onclick=()=>{cleanup();leave();run.disabled=false;};
 run.onclick=async()=>{if(!online){feedback('Esperando conexión a las salas.');return;}run.disabled=true;try{
 testContext=new AudioContext();await testContext.resume();const destination=testContext.createMediaStreamDestination(),gain=testContext.createGain();gain.gain.value=0;testOsc=testContext.createOscillator();testOsc.frequency.value=440;testOsc.connect(gain);gain.connect(destination);testOsc.start();
 const canvas=document.createElement('canvas');canvas.width=480;canvas.height=270;const drawing=canvas.getContext('2d');let tick=0;
 testTimer=setInterval(()=>{tick++;drawing.fillStyle='#193a2a';drawing.fillRect(0,0,480,270);drawing.fillStyle='#d9f99c';drawing.font='bold 32px sans-serif';drawing.fillText('PRUEBA CODEX',70,80);drawing.font='24px sans-serif';drawing.fillText('Video sintético · '+(tick/10).toFixed(1)+' s',65,140);drawing.beginPath();drawing.arc(40+(tick*8)%400,210,18,0,Math.PI*2);drawing.fill();if(tick%20===0){const t=testContext.currentTime;gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(.08,t+.02);gain.gain.linearRampToValueAtTime(0,t+.22);}},100);
 const video=canvas.captureStream(10).getVideoTracks()[0],audio=destination.stream.getAudioTracks()[0];roomAudio.unlock().catch(()=>{});await join('D');voice.local={audio,video};for(const peer of voice.peers.values())for(const kind of ['audio','video'])if(peer[kind])await peer[kind].sender.replaceTrack(voice.local[kind]);updateMic();$('cam').textContent='📷';$('cam').setAttribute('aria-label','Cámara encendida');$('cam').setAttribute('aria-pressed','true');await track();render();feedback('Prueba sintética: imagen animada y tono breve cada 2 segundos.');
 }catch(e){cleanup();run.disabled=false;feedback('Error de prueba: '+e.message);}};
 window.addEventListener('pagehide',cleanup);
}
